package com.runetick;

import java.awt.Color;

/** Highlight color chosen on the site. Titles and marks use this. Prices do not. */
public final class Accent
{
	private static final Color FALLBACK = new Color(0x22, 0xc5, 0x5e);
	private static volatile Color color = FALLBACK;

	private Accent()
	{
	}

	public static Color color()
	{
		return color;
	}

	public static void set(String hex)
	{
		Color next = parse(hex);
		if (next != null)
		{
			color = next;
		}
	}

	static Color parse(String hex)
	{
		if (hex == null)
		{
			return null;
		}
		String s = hex.trim();
		if (s.length() != 7 || s.charAt(0) != '#')
		{
			return null;
		}
		try
		{
			int rgb = Integer.parseInt(s.substring(1), 16);
			return new Color(rgb);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.runetick;

/**
 * How many units you can buy with known cash at a given price, capped by GE limit when set.
 */
final class Afford
{
	private Afford()
	{
	}

	/**
	 * @param cashGp inv + last-known bank (or inv only if bank never opened)
	 * @param buyPrice gp per item
	 * @param limit GE 4h buy limit, or 0 if unknown
	 */
	static long units(long cashGp, long buyPrice, int limit)
	{
		if (buyPrice <= 0 || cashGp <= 0)
		{
			return 0;
		}
		long afford = cashGp / buyPrice;
		if (limit > 0)
		{
			return Math.min(afford, limit);
		}
		return afford;
	}
}

package com.runetick;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

/**
 * Board opportunities that overlap the player's last-seen bank stack.
 */
final class BankHits
{
	private BankHits()
	{
	}

	static List<BoardLine> build(
		Map<Integer, Integer> holdings,
		List<RuneTickApi.FatSpread> fat,
		List<RuneTickApi.Dip> dips,
		List<RuneTickApi.PlacedFlip> placed,
		long minDreamGp,
		long minMarginPerUnit,
		boolean hideAlch,
		int limit)
	{
		List<Hit> hits = new ArrayList<>();
		if (holdings == null || holdings.isEmpty())
		{
			return java.util.Collections.emptyList();
		}

		if (fat != null)
		{
			for (RuneTickApi.FatSpread f : fat)
			{
				if (f == null)
				{
					continue;
				}
				int q = holdings.getOrDefault(f.getId(), 0);
				if (q <= 0)
				{
					continue;
				}
				if (f.getDreamGp() < minDreamGp || f.getMarginPerUnit() < minMarginPerUnit)
				{
					continue;
				}
				hits.add(new Hit(
					f.getId(),
					f.getName(),
					"buy " + PriceFormat.gp(f.getBid()) + " -> sell " + PriceFormat.gp(f.getAsk()),
					"have " + q + " | profit " + PriceFormat.gp(f.getDreamGp()),
					f.getDreamGp()));
			}
		}

		if (dips != null)
		{
			for (RuneTickApi.Dip d : dips)
			{
				if (d == null)
				{
					continue;
				}
				if (hideAlch && d.isAlchFloor())
				{
					continue;
				}
				int q = holdings.getOrDefault(d.getId(), 0);
				if (q <= 0)
				{
					continue;
				}
				long ask = FocusCopy.dipAsk(d.getPrice());
				long margin = ask - d.getPrice();
				if (margin < minMarginPerUnit)
				{
					continue;
				}
				hits.add(new Hit(
					d.getId(),
					d.getName(),
					"dip buy " + PriceFormat.gp(d.getPrice()) + " -> sell " + PriceFormat.gp(ask),
					"have " + q + " | margin " + PriceFormat.gp(margin) + "/ea",
					margin * Math.max(1, q)));
			}
		}

		if (placed != null)
		{
			for (RuneTickApi.PlacedFlip f : placed)
			{
				if (f == null || "done".equals(f.getStatus()))
				{
					continue;
				}
				int q = holdings.getOrDefault(f.getItemId(), 0);
				if (q <= 0)
				{
					continue;
				}
				hits.add(new Hit(
					f.getItemId(),
					f.getItemName(),
					"flip buy " + PriceFormat.gp(f.getBid()) + " -> sell " + PriceFormat.gp(f.getAsk()),
					"have " + q + " | fill " + f.getBought() + "/" + f.getUnits(),
					f.getProfitIfDone()));
			}
		}

		hits.sort(Comparator.comparingLong((Hit h) -> h.score).reversed());
		List<BoardLine> out = new ArrayList<>();
		for (Hit h : hits)
		{
			if (out.size() >= Math.max(1, limit))
			{
				break;
			}
			// Dedupe by item — keep highest-scoring label.
			boolean seen = false;
			for (BoardLine existing : out)
			{
				if (existing.itemId == h.itemId)
				{
					seen = true;
					break;
				}
			}
			if (seen)
			{
				continue;
			}
			out.add(BoardLine.of(h.itemId, h.name, h.mid, h.total));
		}
		return out;
	}

	private static final class Hit
	{
		final int itemId;
		final String name;
		final String mid;
		final String total;
		final long score;

		Hit(int itemId, String name, String mid, String total, long score)
		{
			this.itemId = itemId;
			this.name = name;
			this.mid = mid;
			this.total = total;
			this.score = score;
		}
	}
}

package com.runetick;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Last-seen bank item quantities (canonical tradeable ids). Updated while the bank is open;
 * kept after close so the board can tag fat/dip/flip hits you already hold.
 */
@Singleton
public class BankHoldings
{
	private static final int COINS = ItemID.COINS_995;
	private static final int PLATINUM = ItemID.PLATINUM_TOKEN;

	private final ItemManager itemManager;

	private volatile Map<Integer, Integer> qtyById = Collections.emptyMap();
	private volatile boolean seen;

	@Inject
	public BankHoldings(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	public boolean isSeen()
	{
		return seen;
	}

	public int qty(int itemId)
	{
		if (itemId <= 0)
		{
			return 0;
		}
		Integer q = qtyById.get(itemId);
		return q == null ? 0 : q;
	}

	public Map<Integer, Integer> snapshot()
	{
		return qtyById;
	}

	public void clear()
	{
		qtyById = Collections.emptyMap();
		seen = false;
	}

	/** Call on the client thread while the bank container is available. */
	public void refresh(ItemContainer bank)
	{
		if (bank == null)
		{
			return;
		}
		Map<Integer, Integer> next = new HashMap<>();
		Item[] items = bank.getItems();
		if (items != null)
		{
			for (Item item : items)
			{
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				int raw = item.getId();
				if (raw == COINS || raw == PLATINUM)
				{
					continue;
				}
				int id = canonicalize(raw);
				if (id <= 0 || id == COINS || id == PLATINUM)
				{
					continue;
				}
				next.merge(id, item.getQuantity(), Integer::sum);
			}
		}
		qtyById = Collections.unmodifiableMap(next);
		seen = true;
	}

	private int canonicalize(int itemId)
	{
		try
		{
			return itemManager.canonicalize(itemId);
		}
		catch (Throwable t)
		{
			return itemId;
		}
	}
}

package com.runetick;

/** Same cheap / slow / best cuts as the website fat board. */
public final class BoardCuts
{
	public static final int CHEAP_BID = 10_000;
	public static final double SLOW_CLEARS_PER_HOUR = 20;
	public static final long BEST_DREAM_GP = 5_000_000;
	/** Dips under this many traded per day count as slow. */
	public static final long SLOW_DAILY_VOLUME = 2_000;

	private BoardCuts()
	{
	}

	public static boolean fat(RuneTickApi.FatSpread f, boolean hideCheap, boolean hideSlow, boolean best)
	{
		if (f == null)
		{
			return false;
		}
		boolean cheap = f.getBid() < CHEAP_BID;
		boolean slow = f.getClearsPerHour() < SLOW_CLEARS_PER_HOUR;
		if ((hideCheap || best) && cheap)
		{
			return false;
		}
		if ((hideSlow || best) && slow)
		{
			return false;
		}
		if (best && f.getDreamGp() < BEST_DREAM_GP)
		{
			return false;
		}
		return true;
	}

	public static boolean dip(RuneTickApi.Dip d, boolean hideCheap, boolean hideSlow)
	{
		if (d == null)
		{
			return false;
		}
		if (hideCheap && d.getPrice() < CHEAP_BID)
		{
			return false;
		}
		if (hideSlow && d.getDailyVolume() < SLOW_DAILY_VOLUME)
		{
			return false;
		}
		return true;
	}
}

package com.runetick;

/**
 * One clickable board row: item id + {@link BoardRow} text.
 */
final class BoardLine
{
	final int itemId;
	final String row;

	BoardLine(int itemId, String row)
	{
		this.itemId = itemId;
		this.row = row == null ? "" : row;
	}

	static BoardLine of(int itemId, String name, String mid, String total)
	{
		return new BoardLine(itemId, BoardRow.format(name, mid, total));
	}
}

package com.runetick;

/**
 * One board line: {@code name | buy->sell | total} (ASCII, font-safe).
 */
final class BoardRow
{
	private BoardRow()
	{
	}

	static String format(String name, String mid, String total)
	{
		String n = HudText.ascii(name == null ? "?" : name);
		String m = HudText.ascii(mid == null ? "" : mid);
		String t = HudText.ascii(total == null ? "" : total);
		return n + "\t" + m + "\t" + t;
	}

	static String name(String row)
	{
		return part(row, 0);
	}

	static String mid(String row)
	{
		return part(row, 1);
	}

	static String total(String row)
	{
		return part(row, 2);
	}

	private static String part(String row, int idx)
	{
		if (row == null || row.isEmpty())
		{
			return "";
		}
		String[] bits = row.split("\t", 3);
		return idx < bits.length ? bits[idx] : "";
	}
}

package com.runetick;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.Reader;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Data;
import net.runelite.client.util.Filepath;

/**
 * Last-known inventory and bank cash, so the panel survives a restart.
 */
@Singleton
public class CashStore
{
	@Data
	public static class Snapshot
	{
		private long inventoryGp;
		private long bankGp;
		private boolean bankSeen;
		private long savedAt;
	}

	private final PluginFiles files;
	private final Gson gson;

	@Inject
	public CashStore(PluginFiles files, Gson gson)
	{
		this.files = files;
		this.gson = gson;
	}

	public synchronized Snapshot load()
	{
		try
		{
			Filepath file = files.file("cash.json");
			if (!file.exists())
			{
				return null;
			}
			try (Reader reader = file.openBufferedReader())
			{
				Snapshot s = gson.fromJson(reader, Snapshot.class);
				if (s == null)
				{
					return null;
				}
				s.setInventoryGp(Math.max(0, s.getInventoryGp()));
				s.setBankGp(Math.max(0, s.getBankGp()));
				return s;
			}
		}
		catch (IOException | JsonSyntaxException e)
		{
			return null;
		}
	}

	public synchronized void save(long inventoryGp, long bankGp, boolean bankSeen) throws IOException
	{
		Snapshot s = new Snapshot();
		s.setInventoryGp(Math.max(0, inventoryGp));
		s.setBankGp(Math.max(0, bankGp));
		s.setBankSeen(bankSeen);
		s.setSavedAt(System.currentTimeMillis());
		files.file("cash.json").write(gson.toJson(s));
	}
}

package com.runetick;

import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;

/**
 * Inventory cash is live while logged in. Bank cash is only readable while the bank is open —
 * we keep the last seen bank total in memory and on disk so it survives logout/restart.
 */
@Slf4j
@Singleton
public class CashTracker
{
	private static final int COINS = ItemID.COINS_995;
	private static final int PLATINUM = ItemID.PLATINUM_TOKEN;
	private static final long PLATINUM_VALUE = 1_000L;

	private final Client client;
	private final CashStore store;

	private volatile long inventoryGp;
	private volatile long bankGp;
	private volatile boolean bankSeen;
	private volatile long savedAt;
	private volatile boolean dirty;

	@Inject
	public CashTracker(Client client, CashStore store)
	{
		this.client = client;
		this.store = store;
		restore();
	}

	public long getInventoryGp()
	{
		return inventoryGp;
	}

	public long getBankGp()
	{
		return bankGp;
	}

	public boolean isBankSeen()
	{
		return bankSeen;
	}

	public long getSavedAt()
	{
		return savedAt;
	}

	/** Inventory + last-seen bank (0 bank until opened once, then persists). */
	public long getTotalKnownGp()
	{
		return inventoryGp + (bankSeen ? bankGp : 0);
	}

	public void restore()
	{
		CashStore.Snapshot snap = store.load();
		if (snap == null)
		{
			return;
		}
		inventoryGp = snap.getInventoryGp();
		bankGp = snap.getBankGp();
		bankSeen = snap.isBankSeen();
		savedAt = snap.getSavedAt();
		dirty = false;
	}

	public void refreshInventory()
	{
		long next = countGp(client.getItemContainer(InventoryID.INVENTORY));
		if (next != inventoryGp)
		{
			inventoryGp = next;
			dirty = true;
			persist();
		}
	}

	public void refreshBank()
	{
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			return;
		}
		long next = countGp(bank);
		if (!bankSeen || next != bankGp)
		{
			bankGp = next;
			bankSeen = true;
			dirty = true;
			persist();
		}
	}

	/**
	 * Leave last-known cash alone on logout — only clear the live inventory read so we do not
	 * pretend the bag is still open. Bank cache stays until the next bank open refreshes it.
	 */
	public void onLogout()
	{
		// Keep inventoryGp as last known for panel/site until the next live refresh.
		persist();
	}

	public void persist()
	{
		if (!dirty && savedAt > 0)
		{
			return;
		}
		try
		{
			store.save(inventoryGp, bankGp, bankSeen);
			savedAt = System.currentTimeMillis();
			dirty = false;
		}
		catch (IOException e)
		{
			log.error("Could not save last-known cash", e);
		}
	}

	static long countGp(ItemContainer container)
	{
		if (container == null)
		{
			return 0;
		}
		long coins = container.count(COINS);
		long platinum = container.count(PLATINUM);
		return coins + platinum * PLATINUM_VALUE;
	}
}

package com.runetick;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Stores the last logged offer per GE slot against the current RuneScape account,
 * so an uncollected finished offer is not logged again on the next login.
 */
@Singleton
public class ConfigLoggedOffers implements OfferSync.LoggedOffers
{
	private static final String KEY_PREFIX = "loggedOffer.";

	private final ConfigManager configManager;

	@Inject
	public ConfigLoggedOffers(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	@Override
	public String get(int slot)
	{
		return configManager.getRSProfileConfiguration(RuneTickConfig.GROUP, KEY_PREFIX + slot);
	}

	@Override
	public void put(int slot, String fingerprint)
	{
		configManager.setRSProfileConfiguration(RuneTickConfig.GROUP, KEY_PREFIX + slot, fingerprint);
	}

	@Override
	public void clear(int slot)
	{
		configManager.unsetRSProfileConfiguration(RuneTickConfig.GROUP, KEY_PREFIX + slot);
	}
}

package com.runetick;

/**
 * Human-readable day-trade lines from mean-reversion signals (ASCII for RuneLite font).
 */
final class DayTradeCopy
{
	private DayTradeCopy()
	{
	}

	static String action(RuneTickApi.Signal s)
	{
		if (s == null)
		{
			return "Watch";
		}
		return "cheap".equals(s.getSide()) ? "Buy dip" : "Sell spike";
	}

	static String reason(RuneTickApi.Signal s)
	{
		if (s == null)
		{
			return "";
		}
		double z = s.getZScore24h();
		String strength;
		double abs = Math.abs(z);
		if (abs >= 2.5)
		{
			strength = "strong";
		}
		else if (abs >= 1.5)
		{
			strength = "solid";
		}
		else
		{
			strength = "mild";
		}
		if ("cheap".equals(s.getSide()))
		{
			return strength + " dip | z " + formatZ(z) + " vs 24h";
		}
		return strength + " spike | z " + formatZ(z) + " vs 24h";
	}

	static String prices(RuneTickApi.Signal s)
	{
		if (s == null)
		{
			return "";
		}
		if ("cheap".equals(s.getSide()))
		{
			return "buy <= " + PriceFormat.gp(s.getBuy()) + " -> sell " + PriceFormat.gp(s.getSell());
		}
		return "sell >= " + PriceFormat.gp(s.getSell()) + " (bid " + PriceFormat.gp(s.getBuy()) + ")";
	}

	static String hint(RuneTickApi.Signal s)
	{
		if (s == null)
		{
			return "";
		}
		if (s.getHint() != null && !s.getHint().isEmpty())
		{
			return s.getHint();
		}
		if (s.getMarket() != null && !s.getMarket().isEmpty())
		{
			return s.getMarket();
		}
		return "";
	}

	private static String formatZ(double z)
	{
		return String.format("%+.1f", z);
	}
}

package com.runetick;

/**
 * Fat board slice — mirrors the site's High volume / Expensive filters.
 */
public enum FatStyle
{
	ALL,
	BUSY,
	PRICEY;

	/** ~100 trades / 5m or ~40 clears/h. */
	public static final int BUSY_VOLUME_5M = 100;
	public static final double BUSY_CLEARS_PER_HOUR = 40;
	/** High unit price for the thin/expensive lane. */
	public static final int PRICEY_BID = 50_000;

	public boolean matches(RuneTickApi.FatSpread f)
	{
		if (f == null)
		{
			return false;
		}
		if (this == ALL)
		{
			return true;
		}
		boolean busy = f.getVolume5m() >= BUSY_VOLUME_5M || f.getClearsPerHour() >= BUSY_CLEARS_PER_HOUR;
		if (this == BUSY)
		{
			return busy;
		}
		return f.getBid() >= PRICEY_BID && !busy;
	}
}

package com.runetick;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.FormBody;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The player's Runetick (Firebase) sign-in. Holds the long-lived refresh token handed over by
 * the Runetick website and trades it for short-lived ID tokens that the Runetick API accepts.
 * All network calls block; call from a background thread.
 */
@Singleton
public class FirebaseSession
{
	static final String TOKEN_URL = "https://securetoken.googleapis.com/v1/token";

	/** Errors that mean the sign-in is gone for good and the player has to connect again. */
	private static final Set<String> SIGNED_OUT_ERRORS = new HashSet<>(Arrays.asList(
		"TOKEN_EXPIRED", "USER_DISABLED", "USER_NOT_FOUND", "INVALID_REFRESH_TOKEN", "INVALID_GRANT_TYPE"));

	private static final long EXPIRY_MARGIN_MS = 60_000;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final SessionStore store;
	private final HttpUrl tokenUrl;

	private boolean loaded;
	private SessionStore.Session session;
	private String idToken;
	private long idTokenExpiresAt;

	@Inject
	public FirebaseSession(OkHttpClient httpClient, Gson gson, SessionStore store)
	{
		this(httpClient, gson, store, HttpUrl.parse(TOKEN_URL));
	}

	FirebaseSession(OkHttpClient httpClient, Gson gson, SessionStore store, HttpUrl tokenUrl)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.store = store;
		this.tokenUrl = tokenUrl;
	}

	public synchronized boolean isLinked() throws IOException
	{
		return current() != null;
	}

	public synchronized void link(String apiKey, String refreshToken) throws IOException
	{
		SessionStore.Session s = new SessionStore.Session(apiKey, refreshToken);
		store.save(s);
		session = s;
		loaded = true;
		invalidateIdToken();
	}

	public synchronized void unlink() throws IOException
	{
		session = null;
		loaded = true;
		invalidateIdToken();
		store.clear();
	}

	/** Forget the cached ID token, e.g. after the API rejected it. */
	public synchronized void invalidateIdToken()
	{
		idToken = null;
		idTokenExpiresAt = 0;
	}

	/**
	 * @return a valid ID token, refreshing it if needed
	 * @throws NotLinkedException if the player is not connected, or the sign-in was revoked
	 */
	public synchronized String getIdToken() throws IOException
	{
		SessionStore.Session s = current();
		if (s == null)
		{
			throw new NotLinkedException("Not connected to Runetick");
		}

		if (idToken != null && System.currentTimeMillis() < idTokenExpiresAt - EXPIRY_MARGIN_MS)
		{
			return idToken;
		}

		Request request = new Request.Builder()
			.url(tokenUrl.newBuilder().addQueryParameter("key", s.getApiKey()).build())
			.post(new FormBody.Builder()
				.add("grant_type", "refresh_token")
				.add("refresh_token", s.getRefreshToken())
				.build())
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			ResponseBody body = response.body();
			JsonObject json = parse(body == null ? "" : body.string());

			if (!response.isSuccessful())
			{
				String error = errorMessage(json);
				if (SIGNED_OUT_ERRORS.contains(error))
				{
					unlink();
					throw new NotLinkedException("Runetick sign-in ended (" + error + "); connect again");
				}
				throw new IOException("Runetick sign-in refresh failed: HTTP " + response.code() + " " + error);
			}

			String newIdToken = string(json, "id_token");
			if (newIdToken == null)
			{
				throw new IOException("Runetick sign-in refresh returned no token");
			}

			long expiresInSec = 3600;
			try
			{
				expiresInSec = Long.parseLong(string(json, "expires_in"));
			}
			catch (NumberFormatException e)
			{
				// keep the default
			}

			idToken = newIdToken;
			idTokenExpiresAt = System.currentTimeMillis() + expiresInSec * 1000;

			String rotated = string(json, "refresh_token");
			if (rotated != null && !rotated.equals(s.getRefreshToken()))
			{
				session = new SessionStore.Session(s.getApiKey(), rotated);
				store.save(session);
			}
			return idToken;
		}
	}

	private SessionStore.Session current() throws IOException
	{
		if (!loaded)
		{
			session = store.load();
			loaded = true;
		}
		return session;
	}

	private JsonObject parse(String body)
	{
		try
		{
			JsonObject json = gson.fromJson(body, JsonObject.class);
			return json == null ? new JsonObject() : json;
		}
		catch (JsonParseException e)
		{
			return new JsonObject();
		}
	}

	private static String string(JsonObject json, String key)
	{
		return json.has(key) && json.get(key).isJsonPrimitive() ? json.get(key).getAsString() : null;
	}

	private static String errorMessage(JsonObject json)
	{
		if (json.has("error") && json.get("error").isJsonObject())
		{
			String message = string(json.getAsJsonObject("error"), "message");
			return message == null ? "" : message;
		}
		return "";
	}

	public static class NotLinkedException extends IOException
	{
		public NotLinkedException(String message)
		{
			super(message);
		}
	}
}

package com.runetick;

/**
 * Compact ASCII copy for fat spreads and monthly dips (RuneLite font-safe).
 */
final class FocusCopy
{
	private FocusCopy()
	{
	}

	/** Target sell for a dip buy: ~20% after-tax profit (site evidence). */
	static long dipAsk(long buyPrice)
	{
		if (buyPrice <= 0)
		{
			return 0;
		}
		return Math.max(buyPrice + 1, Math.round(buyPrice * 1.20 / 0.98));
	}

	static String dipPct(RuneTickApi.Dip d)
	{
		if (d == null)
		{
			return "";
		}
		String pct = String.format("-%.0f%%", d.getDip() * 100.0);
		return d.isAlchFloor() ? pct + " alch" : pct;
	}

	static String dipWhy(RuneTickApi.Dip d)
	{
		return dipPct(d);
	}

	/** One-line prices: buy -> sell (usual). */
	static String dipPrices(RuneTickApi.Dip d)
	{
		if (d == null)
		{
			return "";
		}
		return PriceFormat.gp(d.getPrice())
			+ "->"
			+ PriceFormat.gp(dipAsk(d.getPrice()))
			+ " | usual "
			+ PriceFormat.gp(d.getMedian30());
	}

	/** After-tax profit on one item. {@link Long#MIN_VALUE} when a price is missing. */
	static long eachProfit(long buy, long sell)
	{
		if (buy <= 0 || sell <= 0)
		{
			return Long.MIN_VALUE;
		}
		long net = sell;
		if (sell >= 50)
		{
			net = sell - Math.min(5_000_000L, sell * 2 / 100);
		}
		return net - buy;
	}

	static String fatWhy(RuneTickApi.FatSpread f)
	{
		if (f == null)
		{
			return "";
		}
		return PriceFormat.gp(f.getMarginPerUnit()) + "/ea | full " + PriceFormat.gpCompact(f.getDreamGp());
	}

	static String fatPrices(RuneTickApi.FatSpread f)
	{
		if (f == null)
		{
			return "";
		}
		return PriceFormat.gp(f.getBid()) + "->" + PriceFormat.gp(f.getAsk())
			+ " x" + PriceFormat.gp(f.getDreamUnits());
	}

	static String fatMarket(RuneTickApi.FatSpread f)
	{
		if (f == null)
		{
			return "";
		}
		if (f.getMarketHint() != null && !f.getMarketHint().isEmpty())
		{
			return f.getMarketHint();
		}
		return f.getMarket() == null ? "" : f.getMarket();
	}

	static String flipLine(RuneTickApi.PlacedFlip flip)
	{
		if (flip == null)
		{
			return "";
		}
		if ("selling".equals(flip.getStatus()))
		{
			return "sell " + PriceFormat.gp(flip.getAsk())
				+ " | " + flip.getSold() + "/" + flip.getUnits();
		}
		return PriceFormat.gp(flip.getBid()) + "->" + PriceFormat.gp(flip.getAsk())
			+ " | " + flip.getBought() + "/" + flip.getUnits();
	}
}

package com.runetick;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Reads completed GE fills persisted by RuneLite's built-in Grand Exchange plugin.
 */
@Singleton
public class GeHistory
{
	private static final String GROUP = "grandexchange";
	private static final String KEY = "tradeHistory";
	private static final Type LIST = new TypeToken<List<GeTrade>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public GeHistory(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public List<GeTrade> recent(int limit)
	{
		String json = configManager.getRSProfileConfiguration(GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}
		try
		{
			List<GeTrade> trades = gson.fromJson(json, LIST);
			if (trades == null || trades.isEmpty())
			{
				return Collections.emptyList();
			}
			int from = Math.max(0, trades.size() - Math.max(1, limit));
			return trades.subList(from, trades.size());
		}
		catch (JsonSyntaxException e)
		{
			return Collections.emptyList();
		}
	}
}

package com.runetick;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Compact GE tip: hero buy/sell first, fat/dip context, market second.
 */
public class GeOfferOverlay extends OverlayPanel
{
	private static final Color INK = new Color(0xf4, 0xf4, 0xf5);
	private static final Color GAIN = new Color(0x4a, 0xde, 0x80);
	private static final Color MUTED = new Color(0xb0, 0xb0, 0xb0);
	private static final Color WARN = new Color(0xef, 0x44, 0x44);

	private final Client client;
	private final RuneTickConfig config;
	private final RuneTickState state;
	private final OfferGuard offerGuard;

	@Inject
	public GeOfferOverlay(Client client, RuneTickConfig config, RuneTickState state, OfferGuard offerGuard)
	{
		this.client = client;
		this.config = config;
		this.state = state;
		this.offerGuard = offerGuard;
		setPosition(OverlayPosition.TOP_RIGHT);
		setPriority(PRIORITY_HIGH);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setMovable(true);
		setSnappable(true);
		getPanelComponent().setPreferredSize(new Dimension(220, 0));
		getPanelComponent().setBorder(new java.awt.Rectangle(4, 4, 4, 4));
		getPanelComponent().setGap(new java.awt.Point(0, 2));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		try
		{
			return renderSafe(graphics);
		}
		catch (Throwable t)
		{
			return null;
		}
	}

	private Dimension renderSafe(Graphics2D graphics)
	{
		if (!config.showGeTips() || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		Widget pin = client.getWidget(InterfaceID.BANK_PIN, 0);
		if (pin != null && !pin.isHidden())
		{
			return null;
		}
		if (!geOpen())
		{
			return null;
		}

		int itemId = GeView.tipItemId(client);
		return itemId <= 0 ? renderOverview(graphics) : renderItemTip(graphics, itemId);
	}

	private boolean geOpen()
	{
		Widget window = client.getWidget(ComponentID.GRAND_EXCHANGE_WINDOW_CONTAINER);
		if (window != null && !window.isHidden())
		{
			return true;
		}
		Widget offer = client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER);
		if (offer != null && !offer.isHidden())
		{
			return true;
		}
		Widget root = client.getWidget(InterfaceID.GRAND_EXCHANGE, 0);
		return root != null && !root.isHidden();
	}

	private Dimension renderOverview(Graphics2D graphics)
	{
		int free = countFreeSlots();
		title("GE tip");
		row("Slots", (8 - free) + " busy | " + free + " free", MUTED, INK);

		if (config.showCash())
		{
			String bank = state.isBankSeen() ? PriceFormat.gp(state.getBankGp()) : "-";
			row("Cash", "inv " + PriceFormat.gp(state.getInventoryGp()) + " | bank " + bank, MUTED, INK);
		}

		if (config.showFatAndDips())
		{
			List<RuneTickApi.FatSpread> fat = state.getFat();
			if (!fat.isEmpty())
			{
				RuneTickApi.FatSpread f = fat.get(0);
				row("Margin", PriceFormat.abbreviate(f.getName(), 20), MUTED, INK);
				row(FocusCopy.fatPrices(f), PriceFormat.gpCompact(f.getDreamGp()), INK, GAIN);
			}
		}

		return super.render(graphics);
	}

	private Dimension renderItemTip(Graphics2D graphics, int itemId)
	{
		RuneTickApi.ItemQuote quote = state.getGeItem();
		if (quote == null)
		{
			title("GE tip");
			row("Loading tip...", "", MUTED, MUTED);
			return super.render(graphics);
		}

		int realId = state.getGeItemId() > 0 ? state.getGeItemId() : itemId;
		GrandExchangeOffer offer = offerFor(realId);
		long buy = quote.getBuy();
		long sell = quote.getSell();
		if (offer != null && offer.getPrice() > 0)
		{
			if (buying(offer))
			{
				buy = offer.getPrice();
			}
			else
			{
				sell = offer.getPrice();
			}
		}

		title(PriceFormat.abbreviate(quote.getName(), 28));
		row("Buy", PriceFormat.gpExact(buy), MUTED, INK);
		row("Sell", PriceFormat.gpExact(sell), MUTED, INK);

		long each = FocusCopy.eachProfit(buy, sell);
		if (each != Long.MIN_VALUE)
		{
			row("Each", signed(each), MUTED, each >= 0 ? GAIN : WARN);
			int offerQty = offer != null ? offer.getTotalQuantity() : 0;
			if (offerQty > 0)
			{
				row("On offer", signed(each * offerQty), MUTED, each >= 0 ? GAIN : WARN);
			}
		}

		long cash = state.getInventoryGp() + (state.isBankSeen() ? state.getBankGp() : 0);
		int limit = quote.getLimit();
		long afford = Afford.units(cash, buy, limit);
		String affordText = limit > 0
			? PriceFormat.gp(afford) + " / " + PriceFormat.gp(limit)
			: PriceFormat.gp(afford);
		if (!state.isBankSeen())
		{
			affordText = affordText + " inv";
		}
		row("Afford", affordText, MUTED, INK);
		if (each != Long.MIN_VALUE)
		{
			row("Potential", signed(each * afford), MUTED, each >= 0 ? GAIN : WARN);
		}
		if (offer != null && offer.getTotalQuantity() > 0)
		{
			row("Filled", offer.getQuantitySold() + " / " + offer.getTotalQuantity(), MUTED, MUTED);
		}

		addOfferEta(realId, quote);

		return super.render(graphics);
	}

	private static String signed(long gp)
	{
		return (gp > 0 ? "+" : "") + PriceFormat.gpExact(gp);
	}

	private GrandExchangeOffer offerFor(int itemId)
	{
		GrandExchangeOffer selected = offerAt(GeView.selectedSlot(client));
		if (selected != null && selected.getItemId() == itemId)
		{
			return selected;
		}
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return null;
		}
		for (GrandExchangeOffer offer : offers)
		{
			if (offer != null && offer.getItemId() == itemId && offer.getState() != GrandExchangeOfferState.EMPTY)
			{
				return offer;
			}
		}
		return null;
	}

	private GrandExchangeOffer offerAt(int slot)
	{
		if (slot < 0)
		{
			return null;
		}
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null || slot >= offers.length)
		{
			return null;
		}
		GrandExchangeOffer offer = offers[slot];
		if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY || offer.getItemId() <= 0)
		{
			return null;
		}
		return offer;
	}

	private static boolean buying(GrandExchangeOffer offer)
	{
		GrandExchangeOfferState state = offer.getState();
		return state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
	}

	/** Show volume-based ETA when a matching open GE offer (or placed flip) has remaining qty. */
	private void addOfferEta(int itemId, RuneTickApi.ItemQuote quote)
	{
		if (!config.offerEta())
		{
			return;
		}
		int remaining = remainingForItem(itemId);
		if (remaining <= 0)
		{
			return;
		}
		long vol = quote != null ? Math.max(0L, quote.getVolume()) : offerGuard.volumeOf(itemId);
		String eta = OfferEta.format(remaining, vol);
		if (!eta.isEmpty())
		{
			row("Est. fill", eta + (vol > 0 ? " · vol " + PriceFormat.gp(vol) + "/5m" : ""), MUTED, INK);
		}
	}

	private int remainingForItem(int itemId)
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers != null)
		{
			for (GrandExchangeOffer offer : offers)
			{
				if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
				{
					continue;
				}
				if (offer.getItemId() == itemId)
				{
					return Math.max(0, offer.getTotalQuantity() - offer.getQuantitySold());
				}
			}
		}
		RuneTickApi.PlacedFlip placed = state.placedFor(itemId);
		if (placed != null)
		{
			if ("selling".equals(placed.getStatus()))
			{
				return Math.max(0, placed.getBought() - placed.getSold());
			}
			return Math.max(0, placed.getUnits() - placed.getBought());
		}
		return 0;
	}

	private void title(String text)
	{
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(HudText.ascii(text))
			.color(Accent.color())
			.build());
	}

	private void row(String left, String right, Color leftColor, Color rightColor)
	{
		LineComponent.LineComponentBuilder b = LineComponent.builder()
			.left(HudText.ascii(left))
			.leftColor(leftColor);
		if (right != null && !right.isEmpty())
		{
			b.right(HudText.ascii(right)).rightColor(rightColor);
		}
		panelComponent.getChildren().add(b.build());
	}

	private int countFreeSlots()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return 0;
		}
		int free = 0;
		for (GrandExchangeOffer offer : offers)
		{
			if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				free++;
			}
		}
		return free;
	}
}

package com.runetick;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small mark on the item icon in each GE slot.
 * One mark per slot: check hold, plus-minus reprice, cross pull.
 */
public class GeSlotOverlay extends Overlay
{
	private static final Color REPRICE = new Color(0xf4, 0xf4, 0xf5);
	private static final Color PULL = new Color(0xef, 0x44, 0x44);
	private static final Color PLATE = new Color(5, 5, 6, 230);
	private static final Color INK = new Color(0xf4, 0xf4, 0xf5);
	private static final Font GLYPH = new Font(Font.SANS_SERIF, Font.BOLD, 12);
	private static final Font LEGEND = new Font(Font.SANS_SERIF, Font.PLAIN, 11);

	private final Client client;
	private final RuneTickConfig config;
	private final OfferGuard offerGuard;

	@Inject
	public GeSlotOverlay(Client client, RuneTickConfig config, OfferGuard offerGuard)
	{
		this.client = client;
		this.config = config;
		this.offerGuard = offerGuard;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		try
		{
			if (!config.showGeTips() || GeView.offerScreenOpen(client))
			{
				return null;
			}
			GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
			if (offers == null)
			{
				return null;
			}
			for (int slot = 0; slot < offers.length && slot < 8; slot++)
			{
				drawSlot(graphics, slot, offers[slot]);
			}
			drawLegend(graphics);
		}
		catch (Throwable t)
		{
			return null;
		}
		return null;
	}

	private void drawSlot(Graphics2D graphics, int slot, GrandExchangeOffer offer)
	{
		if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY || offer.getItemId() <= 0)
		{
			return;
		}
		Widget widget = client.getWidget(InterfaceID.GE_OFFERS, 7 + slot);
		if (widget == null || widget.isHidden())
		{
			return;
		}
		Rectangle slotBounds = widget.getBounds();
		if (slotBounds == null || slotBounds.width < 16)
		{
			return;
		}
		boolean buy = offer.getState() == GrandExchangeOfferState.BUYING
			|| offer.getState() == GrandExchangeOfferState.BOUGHT
			|| offer.getState() == GrandExchangeOfferState.CANCELLED_BUY;
		String glyph = "\u2713";
		Color glyphColor = Accent.color();
		RuneTickApi.ItemQuote quote = offerGuard.quoteOf(offer.getItemId());
		if (quote != null)
		{
			OfferAlert.Kind kind = OfferAlert.classify(
				buy, offer.getPrice(), quote.getBuy(), quote.getSell(), quote.getAfterTaxSell(), 0);
			if (kind == OfferAlert.Kind.BUY_RAISE || kind == OfferAlert.Kind.SELL_LOWER)
			{
				glyph = "\u00b1";
				glyphColor = REPRICE;
			}
			else if (kind == OfferAlert.Kind.MARGIN_CRUSH)
			{
				glyph = "\u2715";
				glyphColor = PULL;
			}
		}

		int badge = 16;
		int x = slotBounds.x + slotBounds.width - badge - 3;
		int y = slotBounds.y + 3;
		graphics.setColor(PLATE);
		graphics.fillRoundRect(x - 1, y - 1, badge + 2, badge + 2, 6, 6);
		graphics.setColor(glyphColor);
		graphics.drawRoundRect(x - 1, y - 1, badge + 2, badge + 2, 6, 6);
		graphics.setFont(GLYPH);
		FontMetrics fm = graphics.getFontMetrics();
		int tx = x + (badge - fm.stringWidth(glyph)) / 2;
		int ty = y + (badge + fm.getAscent() - fm.getDescent()) / 2 + 1;
		graphics.drawString(glyph, tx, ty);
	}

	/** One line in the top-right of the Grand Exchange window. */
	private void drawLegend(Graphics2D graphics)
	{
		Widget window = client.getWidget(ComponentID.GRAND_EXCHANGE_WINDOW_CONTAINER);
		if (window == null || window.isHidden())
		{
			window = client.getWidget(InterfaceID.GE_OFFERS, 0);
		}
		if (window == null || window.isHidden())
		{
			return;
		}
		Rectangle bounds = window.getBounds();
		if (bounds == null || bounds.width < 80)
		{
			return;
		}
		String[] glyphs = {"\u2713", "\u00b1", "\u2715"};
		String[] words = {"hold", "reprice", "pull"};
		Color[] colors = {Accent.color(), INK, PULL};
		graphics.setFont(LEGEND);
		FontMetrics fm = graphics.getFontMetrics();
		int pad = 6;
		int gap = 10;
		int width = pad * 2;
		for (int i = 0; i < glyphs.length; i++)
		{
			width += fm.stringWidth(glyphs[i] + " " + words[i]);
			if (i < glyphs.length - 1)
			{
				width += gap;
			}
		}
		int height = fm.getHeight() + 6;
		int x = bounds.x + 8;
		int y = bounds.y + bounds.height + 3;
		if (y + height > client.getCanvasHeight() - 2)
		{
			y = Math.max(2, bounds.y - height - 3);
		}
		graphics.setColor(PLATE);
		graphics.fillRoundRect(x, y, width, height, 8, 8);
		int cursor = x + pad;
		int baseline = y + fm.getAscent() + 3;
		for (int i = 0; i < glyphs.length; i++)
		{
			String bit = glyphs[i] + " " + words[i];
			graphics.setColor(colors[i]);
			graphics.drawString(bit, cursor, baseline);
			cursor += fm.stringWidth(bit) + gap;
		}
	}
}

