package com.runetick;

import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.VarPlayer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;

/** Which Grand Exchange item the player is actually looking at. */
final class GeView
{
	private GeView()
	{
	}

	static boolean offerScreenOpen(Client client)
	{
		return shown(client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER))
			|| shown(client.getWidget(InterfaceID.GeOffers.DETAILS))
			|| shown(client.getWidget(InterfaceID.GeOffers.SETUP));
	}

	private static boolean shown(Widget widget)
	{
		return widget != null && !widget.isHidden();
	}

	/** Selected slot, or -1 on the GE home screen. */
	static int selectedSlot(Client client)
	{
		int slot = client.getVarbitValue(VarbitID.GE_SELECTEDSLOT) - 1;
		return slot >= 0 && slot <= 7 ? slot : -1;
	}

	/**
	 * Item on the buy/sell page. An open offer uses that slot's item.
	 * A new offer uses the item just chosen. Home screen returns 0.
	 */
	static int tipItemId(Client client)
	{
		if (!offerScreenOpen(client))
		{
			return 0;
		}
		// The offer you just placed lives on the details page, not in the search varp.
		int fromScreen = itemOn(client.getWidget(InterfaceID.GeOffers.DETAILS));
		if (fromScreen <= 0)
		{
			fromScreen = itemOn(client.getWidget(InterfaceID.GeOffers.SETUP));
		}
		if (fromScreen > 0)
		{
			return fromScreen;
		}
		int fromSlot = itemInSlot(client, selectedSlot(client));
		if (fromSlot > 0)
		{
			return fromSlot;
		}
		return Math.max(0, client.getVarpValue(VarPlayer.CURRENT_GE_ITEM));
	}

	/** Item icon drawn on a setup or details panel. */
	private static int itemOn(Widget widget)
	{
		return itemOn(widget, 0);
	}

	private static int itemOn(Widget widget, int depth)
	{
		if (!shown(widget) || depth > 8)
		{
			return 0;
		}
		if (widget.getItemId() > 0)
		{
			return widget.getItemId();
		}
		int found = firstItem(widget.getStaticChildren(), depth);
		if (found > 0)
		{
			return found;
		}
		found = firstItem(widget.getDynamicChildren(), depth);
		if (found > 0)
		{
			return found;
		}
		found = firstItem(widget.getNestedChildren(), depth);
		if (found > 0)
		{
			return found;
		}
		return firstItem(widget.getChildren(), depth);
	}

	private static int firstItem(Widget[] children, int depth)
	{
		if (children == null)
		{
			return 0;
		}
		for (Widget child : children)
		{
			int id = itemOn(child, depth + 1);
			if (id > 0)
			{
				return id;
			}
		}
		return 0;
	}

	static int itemInSlot(Client client, int slot)
	{
		if (slot < 0)
		{
			return 0;
		}
		GrandExchangeOffer[] offers;
		try
		{
			offers = client.getGrandExchangeOffers();
		}
		catch (Throwable t)
		{
			return 0;
		}
		if (offers == null || slot >= offers.length)
		{
			return 0;
		}
		GrandExchangeOffer offer = offers[slot];
		if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY || offer.getItemId() <= 0)
		{
			return 0;
		}
		return offer.getItemId();
	}

	/** Slot whose widget owns this menu click, or -1. */
	static int slotFromMenu(Client client, int widgetId)
	{
		for (int slot = 0; slot < 8; slot++)
		{
			Widget slotWidget = client.getWidget(InterfaceID.GE_OFFERS, 7 + slot);
			if (slotWidget == null)
			{
				continue;
			}
			if (slotWidget.getId() == widgetId)
			{
				return slot;
			}
			Widget[] children = slotWidget.getDynamicChildren();
			if (children == null)
			{
				children = slotWidget.getChildren();
			}
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child != null && child.getId() == widgetId)
				{
					return slot;
				}
			}
		}
		return -1;
	}
}

package com.runetick;

/**
 * RuneLite's game font only has a small glyph set. Fancy Unicode (braille drag tabs,
 * ellipsis, arrows, middle dots, minus signs) renders as colored tofu squares in overlays.
 * Keep HUD / tip / sidebar copy in plain ASCII.
 */
final class HudText
{
	private HudText()
	{
	}

	/** Strip / replace characters the Runescape font cannot draw. */
	static String ascii(String s)
	{
		if (s == null || s.isEmpty())
		{
			return "";
		}
		StringBuilder out = new StringBuilder(s.length());
		for (int i = 0; i < s.length(); )
		{
			int cp = s.codePointAt(i);
			i += Character.charCount(cp);
			switch (cp)
			{
				case 0x2800: // ⠀..⠿ braille block often used as drag handles
				case 0x28FF:
					break;
				default:
					if (cp >= 0x2800 && cp <= 0x28FF)
					{
						break;
					}
					if (cp == 0x2026 || cp == 0x22EF) // … ⋯
					{
						out.append("...");
					}
					else if (cp == 0x00B7 || cp == 0x2022 || cp == 0x2219 || cp == 0x22C5) // · • ∙ ⋅
					{
						out.append(" | ");
					}
					else if (cp == 0x2192 || cp == 0x21D2 || cp == 0x2794) // → ⇒
					{
						out.append("->");
					}
					else if (cp == 0x2190) // ←
					{
						out.append("<-");
					}
					else if (cp == 0x2013 || cp == 0x2014 || cp == 0x2212) // – — −
					{
						out.append('-');
					}
					else if (cp == 0x00D7 || cp == 0x2715) // × ✕
					{
						out.append('x');
					}
					else if (cp == 0x2264) // ≤
					{
						out.append("<=");
					}
					else if (cp == 0x2265) // ≥
					{
						out.append(">=");
					}
					else if (cp == 0x2019 || cp == 0x2018) // ’ ‘
					{
						out.append('\'');
					}
					else if (cp == 0x201C || cp == 0x201D) // “ ”
					{
						out.append('"');
					}
					else if (cp < 32)
					{
						out.append(' ');
					}
					else if (cp <= 0x7E || Character.isLetterOrDigit(cp) || Character.isSpaceChar(cp))
					{
						out.appendCodePoint(cp);
					}
					else if (cp == ',' || cp == '.' || cp == '/' || cp == '%' || cp == ':' || cp == '+'
						|| cp == '-' || cp == '(' || cp == ')' || cp == '#' || cp == '@' || cp == '='
						|| cp == '?' || cp == '!' || cp == '&' || cp == '\'' || cp == '"' || cp == '|')
					{
						out.appendCodePoint(cp);
					}
					// else drop unsupported glyph
					break;
			}
		}
		return out.toString().replace("  ", " ").trim();
	}
}

package com.runetick;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Live inventory item quantities (canonical ids), excluding coins/plat.
 */
@Singleton
public class InventoryHoldings
{
	private static final int COINS = ItemID.COINS_995;
	private static final int PLATINUM = ItemID.PLATINUM_TOKEN;

	private final ItemManager itemManager;

	private volatile Map<Integer, Integer> qtyById = Collections.emptyMap();
	private volatile boolean seen;

	@Inject
	public InventoryHoldings(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	public boolean isSeen()
	{
		return seen;
	}

	public Map<Integer, Integer> snapshot()
	{
		return qtyById;
	}

	public void refresh(ItemContainer inv)
	{
		if (inv == null)
		{
			return;
		}
		Map<Integer, Integer> next = new HashMap<>();
		Item[] items = inv.getItems();
		if (items != null)
		{
			for (Item item : items)
			{
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				int raw = item.getId();
				if (raw == COINS || raw == PLATINUM)
				{
					continue;
				}
				int id = canonicalize(raw);
				if (id <= 0 || id == COINS || id == PLATINUM)
				{
					continue;
				}
				next.merge(id, item.getQuantity(), Integer::sum);
			}
		}
		qtyById = Collections.unmodifiableMap(next);
		seen = true;
	}

	private int canonicalize(int itemId)
	{
		try
		{
			return itemManager.canonicalize(itemId);
		}
		catch (Throwable t)
		{
			return itemId;
		}
	}
}

