/**
 * Tags inventory / GE inventory items that are open flips or recommended buys.
 */
public class ItemTipOverlay extends WidgetItemOverlay
{
	private static final Color TAG = new Color(0x00, 0xc8, 0x05);

	private final RuneTickConfig config;
	private final RuneTickState state;

	@Inject
	public ItemTipOverlay(RuneTickConfig config, RuneTickState state)
	{
		this.config = config;
		this.state = state;
		// Inv + bank + GE inventory sidebar — avoid the full GE offer widgets (they can blow up).
		showOnInventory();
		showOnBank();
		showOnInterfaces(InterfaceID.GRAND_EXCHANGE_INVENTORY);
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		try
		{
			if (!config.showItemHighlights() || !state.isLinked() || widgetItem == null || itemId <= 0)
			{
				return;
			}

			Map<Integer, String> labels = state.highlightLabels();
			if (labels.isEmpty())
			{
				return;
			}
			// Exact id only — never call ItemManager here. Canonicalize asserts under -ea
			// and a missed catch used to take down the whole client during GE / bank PIN.
			String label = labels.get(itemId);
			if (label == null)
			{
				return;
			}

			Rectangle bounds = widgetItem.getCanvasBounds();
			if (bounds == null)
			{
				return;
			}

			TextComponent text = new TextComponent();
			text.setText(label);
			text.setColor(TAG);
			text.setOutline(true);
			text.setFont(FontManager.getRunescapeSmallFont());
			text.setPosition(new Point(bounds.x, bounds.y + Math.max(0, bounds.height - 2)));
			text.render(graphics);
		}
		catch (Throwable t)
		{
			// AssertionError is an Error, not a RuntimeException — must catch Throwable.
		}
	}
}

package com.runetick;

import java.util.Map;
import java.util.function.ToLongFunction;

/**
 * GE-price estimate for a qty map (coins/plat should already be excluded).
 */
final class ItemValue
{
	private ItemValue()
	{
	}

	static long estimate(Map<Integer, Integer> qtyById, ToLongFunction<Integer> priceOf)
	{
		if (qtyById == null || qtyById.isEmpty() || priceOf == null)
		{
			return 0;
		}
		long sum = 0;
		for (Map.Entry<Integer, Integer> e : qtyById.entrySet())
		{
			if (e == null || e.getKey() == null || e.getValue() == null)
			{
				continue;
			}
			int id = e.getKey();
			int qty = e.getValue();
			if (id <= 0 || qty <= 0)
			{
				continue;
			}
			long price = Math.max(0, priceOf.applyAsLong(id));
			if (price <= 0)
			{
				continue;
			}
			long line = price * (long) qty;
			if (line < 0)
			{
				// overflow — skip this stack rather than wrapping negative
				continue;
			}
			long next = sum + line;
			if (next < sum)
			{
				return Long.MAX_VALUE / 4;
			}
			sum = next;
		}
		return sum;
	}
}

package com.runetick;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.HashMap;
import java.util.Map;

/**
 * One-shot listener on 127.0.0.1 that receives the player's Runetick sign-in from their browser.
 *
 * The plugin opens {@code <site>/link?port=..&state=..}. Once the player confirms there, the site
 * sends the browser to {@code http://127.0.0.1:<port>/callback#state=..&apiKey=..&refreshToken=..}.
 * The page served here reads the fragment (which browsers never send over the network), removes it
 * from the address bar and posts it back to {@code /token}.
 */
public class LinkServer
{
	public interface Listener
	{
		void linked(String apiKey, String refreshToken) throws IOException;
	}

	private static final int MAX_BODY_BYTES = 16 * 1024;

	private static final String CALLBACK_PAGE = "<!doctype html><html><head><meta charset=\"utf-8\">"
		+ "<title>Runetick</title>"
		+ "<style>body{font-family:system-ui,sans-serif;background:#111;color:#eee;display:grid;"
		+ "place-items:center;min-height:100vh;margin:0}p{font-size:1.1rem}</style></head>"
		+ "<body><p id=\"m\">Connecting RuneLite to Runetick\u2026</p><script>"
		+ "var body=location.hash.slice(1);history.replaceState(null,'',location.pathname);"
		+ "var m=document.getElementById('m');"
		+ "fetch('/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body})"
		+ ".then(function(r){m.textContent=r.ok?'RuneLite is connected to Runetick. You can close this tab.'"
		+ ":'Could not connect. Go back to RuneLite and press Connect again.';})"
		+ ".catch(function(){m.textContent='Could not reach RuneLite. Press Connect again.';});"
		+ "</script></body></html>";

	private final HttpServer server;
	private final String state;
	private final Listener listener;
	private boolean stopped;

	public LinkServer(Listener listener) throws IOException
	{
		this.listener = listener;

		byte[] random = new byte[24];
		new SecureRandom().nextBytes(random);
		StringBuilder sb = new StringBuilder();
		for (byte b : random)
		{
			sb.append(String.format("%02x", b));
		}
		state = sb.toString();

		server = HttpServer.create(new InetSocketAddress(InetAddress.getByAddress(new byte[]{127, 0, 0, 1}), 0), 4);
		server.createContext("/callback", this::handleCallback);
		server.createContext("/token", this::handleToken);
		server.start();
	}

	public int getPort()
	{
		return server.getAddress().getPort();
	}

	public String getState()
	{
		return state;
	}

	public synchronized void stop()
	{
		if (!stopped)
		{
			stopped = true;
			server.stop(1);
		}
	}

	/**
	 * Refuse requests addressed to any other host name, so a web page cannot reach this
	 * listener by pointing its own domain at 127.0.0.1.
	 */
	private boolean hostOk(HttpExchange exchange)
	{
		return ("127.0.0.1:" + getPort()).equals(exchange.getRequestHeaders().getFirst("Host"));
	}

	private void handleCallback(HttpExchange exchange) throws IOException
	{
		if (!hostOk(exchange) || !"GET".equals(exchange.getRequestMethod()))
		{
			respond(exchange, 403, "text/plain", "forbidden");
			return;
		}
		respond(exchange, 200, "text/html; charset=utf-8", CALLBACK_PAGE);
	}

	private void handleToken(HttpExchange exchange) throws IOException
	{
		if (!hostOk(exchange) || !"POST".equals(exchange.getRequestMethod()))
		{
			respond(exchange, 403, "text/plain", "forbidden");
			return;
		}

		Map<String, String> form = parseForm(readBody(exchange.getRequestBody()));
		String gotState = form.getOrDefault("state", "");
		String apiKey = form.getOrDefault("apiKey", "");
		String refreshToken = form.getOrDefault("refreshToken", "");

		boolean stateOk = MessageDigest.isEqual(
			state.getBytes(StandardCharsets.UTF_8), gotState.getBytes(StandardCharsets.UTF_8));
		if (!stateOk)
		{
			respond(exchange, 403, "text/plain", "bad state");
			return;
		}
		if (apiKey.isEmpty() || refreshToken.isEmpty())
		{
			respond(exchange, 400, "text/plain", "missing sign-in");
			return;
		}

		try
		{
			listener.linked(apiKey, refreshToken);
		}
		catch (IOException | RuntimeException e)
		{
			respond(exchange, 500, "text/plain", "could not save sign-in");
			throw e;
		}

		respond(exchange, 200, "text/plain", "ok");
		stop();
	}

	private static String readBody(InputStream in) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] buf = new byte[1024];
		int n;
		while ((n = in.read(buf)) != -1)
		{
			out.write(buf, 0, n);
			if (out.size() > MAX_BODY_BYTES)
			{
				throw new IOException("request too large");
			}
		}
		return new String(out.toByteArray(), StandardCharsets.UTF_8);
	}

	static Map<String, String> parseForm(String body)
	{
		Map<String, String> out = new HashMap<>();
		for (String pair : body.split("&"))
		{
			int eq = pair.indexOf('=');
			if (eq <= 0)
			{
				continue;
			}
			try
			{
				out.put(
					URLDecoder.decode(pair.substring(0, eq), StandardCharsets.UTF_8),
					URLDecoder.decode(pair.substring(eq + 1), StandardCharsets.UTF_8));
			}
			catch (IllegalArgumentException e)
			{
				// skip a badly encoded pair
			}
		}
		return out;
	}

	private static void respond(HttpExchange exchange, int status, String contentType, String body) throws IOException
	{
		byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
		exchange.getResponseHeaders().set("Content-Type", contentType);
		exchange.getResponseHeaders().set("Cache-Control", "no-store");
		exchange.sendResponseHeaders(status, bytes.length);
		try (OutputStream os = exchange.getResponseBody())
		{
			os.write(bytes);
		}
	}
}

package com.runetick;

/**
 * Cash + GE-priced items + open GE offers. Bank item value is 0 until the bank has been opened once.
 * Session delta is only meaningful once {@link #sessionArmed} (inv + bank scanned).
 *
 * <p>{@link #invGeGp} is bag cash + bag items + open GE offers (no bank) — the live trading pile.
 */
final class NetWorth
{
	final long cashGp;
	final long inventoryCashGp;
	final long invItemsGp;
	final long bankItemsGp;
	final long offersGp;
	final boolean bankItemsSeen;
	/** Inv cash + inv items + GE offers (excludes bank). */
	final long invGeGp;
	final long totalGp;
	final long sessionDeltaGp;
	final boolean sessionArmed;

	NetWorth(long cashGp, long inventoryCashGp, long invItemsGp, long bankItemsGp, long offersGp,
		boolean bankItemsSeen, long sessionDeltaGp, boolean sessionArmed)
	{
		this.cashGp = Math.max(0, cashGp);
		this.inventoryCashGp = Math.max(0, inventoryCashGp);
		this.invItemsGp = Math.max(0, invItemsGp);
		this.bankItemsGp = Math.max(0, bankItemsGp);
		this.offersGp = Math.max(0, offersGp);
		this.bankItemsSeen = bankItemsSeen;
		long invGe = this.inventoryCashGp + this.invItemsGp + this.offersGp;
		this.invGeGp = invGe < 0 ? Long.MAX_VALUE / 4 : invGe;
		long items = this.invItemsGp + (bankItemsSeen ? this.bankItemsGp : 0);
		long total = this.cashGp + items + this.offersGp;
		this.totalGp = total < 0 ? Long.MAX_VALUE / 4 : total;
		this.sessionDeltaGp = sessionDeltaGp;
		this.sessionArmed = sessionArmed;
	}

	static NetWorth empty()
	{
		return new NetWorth(0, 0, 0, 0, 0, false, 0, false);
	}
}

package com.runetick;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.client.game.ItemManager;

/**
 * Estimates net worth: known cash + GE prices for inventory/bank items + open GE offers.
 *
 * <p>Session delta only starts after inventory <em>and</em> bank have been scanned, so discovering
 * bank wealth mid-login is not counted as profit. GE offer moves after that still count.
 */
@Singleton
public class NetWorthTracker
{
	private final Client client;
	private final ItemManager itemManager;
	private final CashTracker cashTracker;
	private final InventoryHoldings inventoryHoldings;
	private final BankHoldings bankHoldings;

	private volatile long invItemsGp;
	private volatile long bankItemsGp;
	private volatile long offersGp;
	private volatile Long sessionBaseline;
	private volatile boolean sessionArmed;

	@Inject
	public NetWorthTracker(
		Client client,
		ItemManager itemManager,
		CashTracker cashTracker,
		InventoryHoldings inventoryHoldings,
		BankHoldings bankHoldings)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.cashTracker = cashTracker;
		this.inventoryHoldings = inventoryHoldings;
		this.bankHoldings = bankHoldings;
	}

	/** Reprice holdings + GE offers. Call on the client thread. */
	public void revalue()
	{
		invItemsGp = ItemValue.estimate(inventoryHoldings.snapshot(), this::price);
		if (bankHoldings.isSeen())
		{
			bankItemsGp = ItemValue.estimate(bankHoldings.snapshot(), this::price);
		}
		offersGp = OfferValue.estimate(safeOffers(), this::price);
		armSessionIfReady();
	}

	public void onLogout()
	{
		sessionBaseline = null;
		sessionArmed = false;
		offersGp = 0;
		invItemsGp = 0;
		// Keep last bankItemsGp — bank scan persists across logout like CashTracker.
	}

	public NetWorth snapshot()
	{
		long total = totalNow();
		long delta = sessionArmed && sessionBaseline != null ? total - sessionBaseline : 0;
		return new NetWorth(
			cashTracker.getTotalKnownGp(),
			cashTracker.getInventoryGp(),
			invItemsGp,
			bankItemsGp,
			offersGp,
			bankHoldings.isSeen(),
			delta,
			sessionArmed);
	}

	boolean isSessionArmed()
	{
		return sessionArmed;
	}

	Long getSessionBaseline()
	{
		return sessionBaseline;
	}

	private void armSessionIfReady()
	{
		if (sessionArmed)
		{
			return;
		}
		// Need a full picture: bag items scanned + bank opened at least once this install/session.
		if (!SessionDelta.ready(inventoryHoldings.isSeen(), bankHoldings.isSeen()))
		{
			return;
		}
		sessionBaseline = totalNow();
		sessionArmed = true;
	}

	private long totalNow()
	{
		long cash = cashTracker.getTotalKnownGp();
		long items = invItemsGp + (bankHoldings.isSeen() ? bankItemsGp : 0);
		long total = cash + items + offersGp;
		return total < 0 ? Long.MAX_VALUE / 4 : total;
	}

	private GrandExchangeOffer[] safeOffers()
	{
		try
		{
			return client.getGrandExchangeOffers();
		}
		catch (Throwable t)
		{
			return null;
		}
	}

	private long price(int itemId)
	{
		try
		{
			return Math.max(0, itemManager.getItemPrice(itemId));
		}
		catch (Throwable t)
		{
			return 0;
		}
	}
}

package com.runetick;

/**
 * Heuristics for adverse market moves against an open GE offer.
 */
public final class OfferAlert
{
	/** Fire when market moves ≥ this fraction against the offer. */
	public static final double ADVERSE_PCT = 0.02;
	/** After-tax margin floor (gp/ea) before margin-crush alert. */
	public static final long MARGIN_FLOOR_GP = 50;

	public enum Kind
	{
		NONE,
		BUY_RAISE,
		SELL_LOWER,
		MARGIN_CRUSH
	}

	private OfferAlert()
	{
	}

	/**
	 * @param buy          true if this is a buy offer
	 * @param offerPrice   your bid (buy) or ask (sell)
	 * @param marketBuy    live wiki buy / high
	 * @param marketSell   live wiki sell / low
	 * @param afterTaxSell live after-tax sell (0 if unknown)
	 * @param costBasis    your buy price for margin check (0 to skip)
	 */
	public static Kind classify(boolean buy, long offerPrice, long marketBuy, long marketSell,
		long afterTaxSell, long costBasis)
	{
		if (offerPrice <= 0)
		{
			return Kind.NONE;
		}
		if (buy)
		{
			// market buy ≥ bid × 1.02
			if (marketBuy > 0 && marketBuy * 100L >= offerPrice * 102L)
			{
				return Kind.BUY_RAISE;
			}
		}
		else
		{
			// market sell ≤ ask × 0.98
			if (marketSell > 0 && marketSell * 100L <= offerPrice * 98L)
			{
				return Kind.SELL_LOWER;
			}
			if (costBasis > 0 && afterTaxSell > 0)
			{
				long margin = afterTaxSell - costBasis;
				if (margin < MARGIN_FLOOR_GP)
				{
					return Kind.MARGIN_CRUSH;
				}
			}
		}
		return Kind.NONE;
	}

	public static String fingerprint(int slot, int itemId, Kind kind)
	{
		return slot + ":" + itemId + ":" + (kind == null ? "NONE" : kind.name());
	}

	public static String message(Kind kind, String itemName)
	{
		String name = itemName == null || itemName.isEmpty() ? "offer" : itemName;
		switch (kind)
		{
			case BUY_RAISE:
				return name + ": market buy rose — raise bid or cancel";
			case SELL_LOWER:
				return name + ": market sell fell — lower ask or cancel";
			case MARGIN_CRUSH:
				return name + ": after-tax margin crushed — reconsider";
			default:
				return "";
		}
	}
}

package com.runetick;

/**
 * Volume-based fill/sale ETA (wiki 5m volume → hourly pace).
 * Same spirit as site {@code clearsPerHour}: rate ≈ volume5m × 12.
 */
public final class OfferEta
{
	private OfferEta()
	{
	}

	/** Estimated units clearing per hour from 5-minute volume. */
	public static long ratePerHour(long volume5m)
	{
		if (volume5m <= 0)
		{
			return 0;
		}
		return volume5m * 12L;
	}

	/**
	 * Remaining units → estimated minutes at volume pace.
	 * Returns 0 when nothing left; Long.MAX_VALUE when volume is dead (caller shows "slow").
	 */
	public static long etaMinutes(int remaining, long volume5m)
	{
		if (remaining <= 0)
		{
			return 0;
		}
		long rate = ratePerHour(volume5m);
		if (rate <= 0)
		{
			return Long.MAX_VALUE;
		}
		long perHour = Math.max(1L, rate);
		return Math.max(1L, (remaining * 60L + perHour - 1) / perHour);
	}

	/** Compact label: {@code ~12m}, {@code ~2h}, {@code slow}, or {@code done}. */
	public static String format(int remaining, long volume5m)
	{
		if (remaining <= 0)
		{
			return "done";
		}
		long mins = etaMinutes(remaining, volume5m);
		if (mins == Long.MAX_VALUE || mins > 24L * 60L)
		{
			return "slow";
		}
		if (mins < 60)
		{
			return "~" + mins + "m";
		}
		long hours = mins / 60;
		if (hours < 48)
		{
			return "~" + hours + "h";
		}
		return "slow";
	}
}

package com.runetick;

import lombok.Value;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Immutable snapshot of a Grand Exchange offer.
 */
@Value
public class OfferEvent
{
	int slot;
	int itemId;
	GrandExchangeOfferState state;
	long price;
	int totalQuantity;
	int quantityFilled;
	long spent;
	long timestamp;

	public static OfferEvent of(int slot, GrandExchangeOffer offer, long timestampMillis)
	{
		return new OfferEvent(
			slot,
			offer.getItemId(),
			offer.getState(),
			offer.getPrice(),
			offer.getTotalQuantity(),
			offer.getQuantitySold(),
			offer.getSpent(),
			timestampMillis
		);
	}

	public boolean isBuy()
	{
		return state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
	}

	/**
	 * True once the offer can no longer fill: completed or cancelled.
	 */
	public boolean isFinished()
	{
		return state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.SOLD
			|| state == GrandExchangeOfferState.CANCELLED_BUY
			|| state == GrandExchangeOfferState.CANCELLED_SELL;
	}

	/**
	 * Average gp actually paid or received per item (before tax), or 0 if nothing filled.
	 */
	public long unitPrice()
	{
		return quantityFilled > 0 ? Math.round((double) spent / quantityFilled) : 0;
	}

	/**
	 * Identifies this exact finished offer, so it is only logged once across logins.
	 */
	public String fingerprint()
	{
		return itemId + ":" + state + ":" + quantityFilled + ":" + spent;
	}

	/**
	 * True when both events describe the same offer state, ignoring the timestamp.
	 */
	public boolean sameOfferAs(OfferEvent other)
	{
		return other != null
			&& slot == other.slot
			&& itemId == other.itemId
			&& state == other.state
			&& price == other.price
			&& totalQuantity == other.totalQuantity
			&& quantityFilled == other.quantityFilled
			&& spent == other.spent;
	}
}

package com.runetick;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Polls item quotes for live GE offers: ETA labels + adverse price desktop alerts (deduped).
 */
@Slf4j
@Singleton
public class OfferGuard
{
	private final RuneTickApi api;
	private final RuneTickConfig config;

	/** slot -> last fired alert fingerprint still active. */
	private final Map<Integer, String> fired = new ConcurrentHashMap<>();
	/** itemId -> last quote volume (5m). */
	private final Map<Integer, Long> volumes = new ConcurrentHashMap<>();
	/** itemId -> last quote for GE tip / margin. */
	private final Map<Integer, RuneTickApi.ItemQuote> quotes = new ConcurrentHashMap<>();
	private volatile List<LiveRow> liveRows = Collections.emptyList();

	@Inject
	public OfferGuard(RuneTickApi api, RuneTickConfig config)
	{
		this.api = api;
		this.config = config;
	}

	public List<LiveRow> getLiveRows()
	{
		return liveRows;
	}

	public long volumeOf(int itemId)
	{
		return volumes.getOrDefault(itemId, 0L);
	}

	public RuneTickApi.ItemQuote quoteOf(int itemId)
	{
		return quotes.get(itemId);
	}

	public String etaFor(int itemId, int remaining)
	{
		if (!config.offerEta())
		{
			return "";
		}
		return OfferEta.format(remaining, volumeOf(itemId));
	}

	/**
	 * Refresh quotes for the given live offers (call off the client thread).
	 * @param notifyDesktop receives alert messages to show
	 */
	public void poll(List<RuneTickApi.GeLiveOffer> offers, Consumer<String> notifyDesktop)
	{
		if (offers == null)
		{
			offers = Collections.emptyList();
		}
		Set<Integer> activeSlots = new HashSet<>();
		Set<Integer> needed = new HashSet<>();
		for (RuneTickApi.GeLiveOffer o : offers)
		{
			if (o == null || o.getItemId() <= 0)
			{
				continue;
			}
			activeSlots.add(o.getSlot());
			needed.add(o.getItemId());
		}
		fired.keySet().removeIf(slot -> !activeSlots.contains(slot));

		Map<Integer, RuneTickApi.ItemQuote> fetched = new HashMap<>();
		for (int itemId : needed)
		{
			try
			{
				RuneTickApi.ItemQuote q = api.getItem(itemId);
				if (q != null)
				{
					fetched.put(itemId, q);
					volumes.put(itemId, Math.max(0L, q.getVolume()));
					quotes.put(itemId, q);
				}
			}
			catch (Throwable t)
			{
				log.error("OfferGuard quote failed for item " + itemId, t);
			}
		}
		volumes.keySet().removeIf(id -> !needed.contains(id));
		quotes.keySet().removeIf(id -> !needed.contains(id));

		List<LiveRow> rows = new ArrayList<>();
		boolean alertsOn = config.offerPriceAlerts() && config.desktopNotify();
		boolean etaOn = config.offerEta();

		for (RuneTickApi.GeLiveOffer o : offers)
		{
			if (o == null || o.getItemId() <= 0)
			{
				continue;
			}
			RuneTickApi.ItemQuote q = fetched.getOrDefault(o.getItemId(), quotes.get(o.getItemId()));
			long vol = q == null ? volumeOf(o.getItemId()) : Math.max(0L, q.getVolume());
			int remaining = Math.max(0, o.getTotal() - o.getFilled());
			String eta = etaOn ? OfferEta.format(remaining, vol) : "";

			boolean buy = !"sell".equalsIgnoreCase(o.getSide());
			long mktBuy = q == null ? 0 : q.getBuy();
			long mktSell = q == null ? 0 : q.getSell();
			long afterTax = q == null ? 0 : q.getAfterTaxSell();
			long costBasis = 0;
			if (!buy)
			{
				// Best-effort: use spent/filled as unit cost when available.
				if (o.getFilled() > 0 && o.getSpent() > 0)
				{
					costBasis = o.getSpent() / o.getFilled();
				}
			}
			OfferAlert.Kind kind = OfferAlert.classify(buy, o.getPrice(), mktBuy, mktSell, afterTax, costBasis);
			String fp = OfferAlert.fingerprint(o.getSlot(), o.getItemId(), kind);
			if (alertsOn && kind != OfferAlert.Kind.NONE)
			{
				String prev = fired.get(o.getSlot());
				if (!fp.equals(prev))
				{
					fired.put(o.getSlot(), fp);
					String msg = OfferAlert.message(kind, o.getItemName());
					if (msg != null && !msg.isEmpty() && notifyDesktop != null)
					{
						try
						{
							notifyDesktop.accept(msg);
						}
						catch (Throwable t)
						{
							log.error("OfferGuard notify failed", t);
						}
					}
				}
			}
			else if (kind == OfferAlert.Kind.NONE)
			{
				fired.remove(o.getSlot());
			}

			rows.add(new LiveRow(
				o.getSlot(),
				o.getItemId(),
				o.getItemName(),
				buy ? "buy" : "sell",
				o.getPrice(),
				o.getFilled(),
				o.getTotal(),
				eta,
				kind));
		}
		liveRows = Collections.unmodifiableList(rows);
	}

	public void clear()
	{
		fired.clear();
		volumes.clear();
		quotes.clear();
		liveRows = Collections.emptyList();
	}

	public static final class LiveRow
	{
		public final int slot;
		public final int itemId;
		public final String name;
		public final String side;
		public final long price;
		public final int filled;
		public final int total;
		public final String eta;
		public final OfferAlert.Kind alert;

		LiveRow(int slot, int itemId, String name, String side, long price, int filled, int total,
			String eta, OfferAlert.Kind alert)
		{
			this.slot = slot;
			this.itemId = itemId;
			this.name = name == null ? ("#" + itemId) : name;
			this.side = side;
			this.price = price;
			this.filled = filled;
			this.total = total;
			this.eta = eta == null ? "" : eta;
			this.alert = alert == null ? OfferAlert.Kind.NONE : alert;
		}
	}
}

package com.runetick;

import java.io.IOException;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Decides what a Grand Exchange offer update means for the player's Runetick account:
 * progress on a flip they placed there, or a finished trade for their trade log.
 * Calls block; use a background thread.
 */
@Singleton
public class OfferSync
{
	/** Remembers which finished offer was last logged per GE slot, across logins. */
	public interface LoggedOffers
	{
		String get(int slot);

		void put(int slot, String fingerprint);

		void clear(int slot);
	}

	public enum Result
	{
		IGNORED, PLACED_UPDATED, TRADE_LOGGED
	}

	private final RuneTickApi api;
	private final RuneTickConfig config;
	private final FirebaseSession session;
	private final LoggedOffers logged;

	@Inject
	public OfferSync(RuneTickApi api, RuneTickConfig config, FirebaseSession session, LoggedOffers logged)
	{
		this.api = api;
		this.config = config;
		this.session = session;
		this.logged = logged;
	}

	public Result handle(OfferEvent event, String itemName) throws IOException
	{
		int filled = event.getQuantityFilled();
		if (filled <= 0 || !session.isLinked())
		{
			return Result.IGNORED;
		}

		if (config.syncPlaced())
		{
			RuneTickApi.PlacedFlip flip = findFlip(api.getPlaced(), event);
			if (flip != null)
			{
				// Runetick logs the trade itself when the flip completes, so never log it here too.
				return updateFlip(flip, event) ? Result.PLACED_UPDATED : Result.IGNORED;
			}
		}

		if (config.logTrades() && event.isFinished())
		{
			String fingerprint = event.fingerprint();
			if (fingerprint.equals(logged.get(event.getSlot())))
			{
				return Result.IGNORED;
			}
			api.logTrade(event.getItemId(), itemName, event.isBuy(), filled, event.unitPrice());
			logged.put(event.getSlot(), fingerprint);
			return Result.TRADE_LOGGED;
		}

		return Result.IGNORED;
	}

	/** The slot was emptied in game, so the next offer in it is a new one even if it looks identical. */
	public void slotEmptied(int slot)
	{
		logged.clear(slot);
	}

	/**
	 * The oldest placed flip for this item that is still waiting on this side of the trade.
	 * The API lists flips newest first.
	 */
	private static RuneTickApi.PlacedFlip findFlip(List<RuneTickApi.PlacedFlip> placed, OfferEvent event)
	{
		RuneTickApi.PlacedFlip match = null;
		for (RuneTickApi.PlacedFlip f : placed)
		{
			if (f.getItemId() != event.getItemId())
			{
				continue;
			}
			boolean waiting = event.isBuy() ? f.getBought() < f.getUnits() : f.getSold() < f.getUnits();
			if (waiting)
			{
				match = f;
			}
		}
		return match;
	}

	/**
	 * Counts only ever go up: offers are re-sent on every login and must not undo progress.
	 */
	private boolean updateFlip(RuneTickApi.PlacedFlip flip, OfferEvent event) throws IOException
	{
		int filled = Math.min(flip.getUnits(), event.getQuantityFilled());
		if (event.isBuy())
		{
			if (filled <= flip.getBought())
			{
				return false;
			}
			api.updatePlaced(flip.getId(), filled, null);
			return true;
		}

		if (filled <= flip.getSold())
		{
			return false;
		}
		// Runetick caps sold at bought; if the buy happened before the plugin was watching, catch bought up.
		Integer bought = filled > flip.getBought() ? filled : null;
		api.updatePlaced(flip.getId(), bought, filled);
		return true;
	}
}

package com.runetick;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Turns raw Grand Exchange offer updates into {@link OfferEvent}s, dropping
 * empty slots and repeats (the client re-sends every slot on each login).
 */
public class OfferTracker
{
	private final Map<Integer, OfferEvent> lastBySlot = new HashMap<>();

	/**
	 * @return the event to export, or null if this update should be ignored
	 */
	public synchronized OfferEvent track(int slot, GrandExchangeOffer offer, long timestampMillis)
	{
		if (offer == null || offer.getState() == null)
		{
			return null;
		}

		if (offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			lastBySlot.remove(slot);
			return null;
		}

		OfferEvent event = OfferEvent.of(slot, offer, timestampMillis);
		if (event.sameOfferAs(lastBySlot.get(slot)))
		{
			return null;
		}

		lastBySlot.put(slot, event);
		return event;
	}

	public synchronized void reset()
	{
		lastBySlot.clear();
	}
}

package com.runetick;

import java.util.function.ToLongFunction;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Mark-to-market value of open / collectable GE offers.
 *
 * <p>Buy: unfilled remainder is still your locked cash at the offer price; filled units waiting
 * to collect are items at GE price.
 *
 * <p>Sell: unsold remainder is items at GE price; {@code spent} is coins waiting to collect.
 */
final class OfferValue
{
	private OfferValue()
	{
	}

	static long estimate(GrandExchangeOffer[] offers, ToLongFunction<Integer> marketPriceOf)
	{
		if (offers == null || offers.length == 0)
		{
			return 0;
		}
		long sum = 0;
		for (GrandExchangeOffer offer : offers)
		{
			long v = one(offer, marketPriceOf);
			long next = sum + v;
			if (next < sum)
			{
				return Long.MAX_VALUE / 4;
			}
			sum = next;
		}
		return sum;
	}

	static long one(GrandExchangeOffer offer, ToLongFunction<Integer> marketPriceOf)
	{
		if (offer == null)
		{
			return 0;
		}
		GrandExchangeOfferState state = offer.getState();
		if (state == null || state == GrandExchangeOfferState.EMPTY)
		{
			return 0;
		}
		int itemId = offer.getItemId();
		int total = Math.max(0, offer.getTotalQuantity());
		int filled = Math.max(0, Math.min(total, offer.getQuantitySold()));
		int remain = Math.max(0, total - filled);
		long offerPrice = Math.max(0, offer.getPrice());
		long spent = Math.max(0, offer.getSpent());
		long market = 0;
		if (itemId > 0 && marketPriceOf != null)
		{
			market = Math.max(0, marketPriceOf.applyAsLong(itemId));
		}

		boolean buy = state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;

		if (buy)
		{
			// Locked cash still sitting on the offer + filled items not yet collected.
			long lockedCash = remain * offerPrice;
			long itemsWaiting = filled * (market > 0 ? market : offerPrice);
			return add(lockedCash, itemsWaiting);
		}

		// Sell / cancelled sell: unsold stock + coins from fills waiting to collect.
		long itemsWaiting = remain * (market > 0 ? market : offerPrice);
		return add(itemsWaiting, spent);
	}

	private static long add(long a, long b)
	{
		long n = a + b;
		return n < 0 ? Long.MAX_VALUE / 4 : n;
	}
}

package com.runetick;

import java.io.IOException;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;

/**
 * Plugin data directory from {@code Plugin#getPluginDirectory()}.
 * Call {@link #use} during startup before any file is read.
 */
@Singleton
public class PluginFiles
{
	private Filepath root;

	public void use(Filepath root)
	{
		this.root = root;
	}

	public Filepath file(String name) throws IOException
	{
		if (root == null)
		{
			throw new IOException("plugin directory is not ready");
		}
		if (!root.exists())
		{
			root.createDirectories();
		}
		return root.joinSegment(name);
	}
}

package com.runetick;

/**
 * Gold formatting. Offer / tip prices are always exact — never "4.4k".
 */
final class PriceFormat
{
	private PriceFormat()
	{
	}

	/**
	 * Exact gp with commas (e.g. {@code 4,412}). Use for buy/sell offers and GE tips.
	 */
	static String gp(long value)
	{
		long abs = Math.abs(value);
		String sign = value < 0 ? "-" : "";
		return sign + withCommas(abs);
	}

	/** Exact with a {@code gp} suffix. */
	static String gpExact(long value)
	{
		return gp(value) + " gp";
	}

	/**
	 * Compact only for huge aggregates (cash totals, gp/hour) where exact would blow the HUD.
	 * Still unambiguous: {@code 12.35m} not {@code 12m}.
	 */
	static String gpCompact(long value)
	{
		long abs = Math.abs(value);
		String sign = value < 0 ? "-" : "";
		if (abs >= 1_000_000_000L)
		{
			return sign + trim2(abs / 1_000_000_000.0) + "b";
		}
		if (abs >= 1_000_000L)
		{
			return sign + trim2(abs / 1_000_000.0) + "m";
		}
		if (abs >= 100_000L)
		{
			// e.g. 440.5k — still more digits than 4.4k
			return sign + trim1(abs / 1_000.0) + "k";
		}
		return sign + withCommas(abs);
	}

	private static String trim1(double v)
	{
		String s = String.format("%.1f", v);
		if (s.endsWith(".0"))
		{
			return s.substring(0, s.length() - 2);
		}
		return s;
	}

	private static String trim2(double v)
	{
		String s = String.format("%.2f", v);
		if (s.endsWith("0") && s.contains("."))
		{
			s = s.substring(0, s.length() - 1);
		}
		if (s.endsWith(".0"))
		{
			return s.substring(0, s.length() - 2);
		}
		if (s.endsWith("."))
		{
			return s.substring(0, s.length() - 1);
		}
		return s;
	}

	private static String withCommas(long abs)
	{
		return String.format("%,d", abs);
	}

	static String abbreviate(String name, int max)
	{
		if (name == null || name.isEmpty())
		{
			return "?";
		}
		return name.length() <= max ? name : name.substring(0, Math.max(1, max - 1)) + "...";
	}

	/** Bid->ask pair with exact prices. */
	static String spread(long bid, long ask)
	{
		return gp(bid) + " -> " + gp(ask);
	}
}

