		text.setOpaque(false);
		String name = quote.getName() == null || quote.getName().isEmpty() ? "Item" : quote.getName();
		JLabel nameLbl = plain(FontManager.getRunescapeBoldFont(), INK);
		nameLbl.setText(wrap(name));
		fitWrapped(nameLbl);
